package main

import (
	"fmt"
	"net/url"
	"strings"
)

func isValidDomain(target string, domain string) bool {
	parsedURL, err := url.Parse(target)
	if err != nil {
		return false
	}

	hostname := parsedURL.Hostname()
	return hostname == domain || strings.HasSuffix(hostname, "."+domain)
}

func main() {
	fmt.Println(isValidDomain("https://music.example.com", "example.com")) // true
	fmt.Println(isValidDomain("https://malicious-example.com", "example.com")) // false
}
